  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B007",
      "proposed_laureates": ["Peter W. Shor", "Andrew M. Steane", "Alexei Kitaev"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected against noise and made fault-tolerant computation a physically coherent goal. Its conceptual influence extends well beyond computing.",
        "attribution": "Shor's factoring algorithm exposed the importance of quantum computation; Steane and Shor developed influential quantum codes, while Kitaev established the topological route to fault tolerance. The field's breadth makes a three-person division necessarily selective.",
        "maturity": "The theory is mature and experimental demonstrations of error correction and logical operations are substantial, though scalable, fault-tolerant computation remains unachieved.",
        "uncertainties": ["How much weight to give a foundational framework whose ultimate large-scale physical realization is still incomplete."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B016",
      "proposed_laureates": ["Alexandre Blais", "Andreas Wallraff", "Robert J. Schoelkopf"],
      "assessment": {
        "nobel_worthiness": "Circuit QED established a controllable regime in which superconducting artificial atoms interact strongly with microwave photons, opening a rich experimental field and a leading quantum technology platform.",
        "attribution": "Blais provided the key theoretical proposal; Wallraff and Schoelkopf led landmark experimental demonstrations and the development of the platform. Steven Girvin also made important theoretical contributions, making any three-person selection incomplete.",
        "maturity": "The central physics has been repeatedly demonstrated and extended across laboratories. Its connection to quantum computing is strong, though the award case should rest on the new physics and experimental control, not the promise of applications.",
        "uncertainties": ["The boundary between this contribution and the recently recognized physics of superconducting circuits needs careful consideration."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": ["Alexander A. Belavin", "Alexander B. Zamolodchikov", "Alexander M. Polyakov"],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory gave exact, powerful methods for understanding critical phenomena and influenced statistical physics and quantum field theory far beyond its original setting.",
        "attribution": "The seminal work is unusually well defined in the Belavin, Polyakov, and Zamolodchikov collaboration, with substantial credit to all three.",
        "maturity": "The framework has been extensively developed and its results connect closely to observed critical behavior. The contribution is mature and its impact sustained.",
        "uncertainties": ["The committee would need to articulate the specific physical discovery at the heart of a contribution that is partly a theoretical method."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enabled stringent tests of fundamental physics, while bringing atomic coherence and control to an exceptional level.",
        "attribution": "Katori's lattice-clock proposal and development and Ye's precision experiments and clock advances are central, complementary contributions.",
        "maturity": "The technology is well demonstrated by multiple groups, with steadily improving accuracy and important applications in metrology and tests of physical laws.",
        "uncertainties": ["The case should distinguish the foundational clock innovation from the broader, ongoing development of precision metrology."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": ["Charles H. Bennett", "Gilles Brassard", "Artur Ekert"],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution turned the nonclassical properties of quantum states into a precise and influential information task, connecting foundational quantum mechanics to secure communication.",
        "attribution": "Bennett and Brassard introduced the first influential protocol, while Ekert developed an entanglement-based approach that made the connection to Bell tests especially clear. These are distinct, major contributions.",
        "maturity": "The principles are experimentally established and protocols have been implemented over increasing distances and in satellite links, though practical systems still face engineering and security constraints.",
        "uncertainties": ["The 2022 physics prize already recognized foundational quantum information and entanglement, so the remaining distinct contribution must be sharply defined."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B020",
      "proposed_laureates": ["Juan Ignacio Cirac", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Theoretical proposals for trapped-ion quantum computing and atomic quantum simulation helped define how quantum systems can be used to compute and model otherwise difficult many-body physics.",
        "attribution": "Cirac and Zoller jointly made central early proposals, with a clear and defensible attribution to both.",
        "maturity": "The ideas have been realized in impressive trapped-ion experiments and have supported a mature research field, although fault-tolerant computing is still developing.",
        "uncertainties": ["The contribution overlaps conceptually with quantum error correction and other quantum-computing platforms, which complicates the scope of a prize."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B024",
      "proposed_laureates": ["Charles L. Kane", "Eugene J. Mele", "Laurens W. Molenkamp"],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators established a new way to classify electronic phases and link bulk topology to robust boundary states.",
        "attribution": "Kane and Mele developed the influential theoretical framework; Molenkamp's experiments established the quantum spin Hall effect in a material system. Later experimental work by others broadened the field.",
        "maturity": "The initial phenomena and topological framework are well established, though materials quality and the scope of protected transport vary across systems.",
        "uncertainties": ["The candidate's broad framing spans related developments and raises questions about the boundaries of the contribution and credit."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B006",
      "proposed_laureates": ["Christopher Jarzynski", "Gavin E. Crooks", "Udo Seifert"],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations and stochastic thermodynamics extended thermodynamic reasoning to small systems driven far from equilibrium, with lasting conceptual and experimental influence.",
        "attribution": "Jarzynski and Crooks derived central relations, while Seifert developed a broad stochastic-thermodynamic framework. Denis Evans also has an important claim through early fluctuation theorems, making selection among contributors difficult.",
        "maturity": "The theory is well developed and supported by experiments on small systems, although its significance for a unified understanding of nonequilibrium physics continues to evolve.",
        "uncertainties": ["The breadth of contributors and the relationship between the original theorems and the later field make a compact attribution challenging."]
      }
    }
  ]
}
